import { Group, Mesh, PlaneGeometry, MeshBasicNodeMaterial } from 'three/webgpu';
import { vec3, uv, mix, smoothstep, time, Fn, vec2, uniform } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const group = new THREE.Group();
  group.name = 'journal-title';

  // Palette
  const ink = '#16161d';
  const paper = '#e8ecf2';
  const accent = '#ff2a38';
  const surface = '#0b0b10';

  // ---- Atlas sprite plane (floating accent) ----
  // Atlas region 0,0,512,320 -> aspect 1.6
  const atlasW = 512;
  const atlasH = 320;
  const aspect = atlasW / atlasH;
  const planeW = 2.4;
  const planeH = planeW / aspect;

  const spriteMat = new MeshBasicNodeMaterial({
    transparent: true,
    depthWrite: false,
  });

  // UV offset for atlas region 0,0,512,320 (full atlas assumed same size)
  const u0 = 0 / atlasW;
  const v0 = 1 - (320 / atlasH); // flip Y
  const u1 = 512 / atlasW;
  const v1 = 1 - (0 / atlasH);

  let spriteMesh = null;
  const texLayer = ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
    tex.colorSpace = THREE.SRGBColorSpace;
    spriteMat.map = tex;
    spriteMat.transparent = true;
    spriteMat.needsUpdate = true;
  }).catch(() => {});

  // Remap UVs through tsl for atlas cropping
  const remappedUV = vec2(
    uv().x.mul(u1 - u0).add(u0),
    uv().y.mul(v1 - v0).add(v0)
  );
  spriteMat.mapUV = remappedUV; // hint (basic material uses .map with default uv in webgpu; remap via override below)

  // MeshBasicNodeMaterial uses uv() in its internal map sampling; to remap we drive the color directly:
  spriteMat.colorNode = Fn(() => {
    const c = texture ? texture.sample(remappedUV) : vec3(1.0);
    return c;
  })(); // will set after texture ready

  // Actually MeshBasicNodeMaterial.map is sampled via uv() automatically. To force atlas crop, override colorNode with texture-dependent sample. We'll set up below once texture loads.
  spriteMat.map = null;
  let atlasTexture = null;
  ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
    atlasTexture = tex;
    tex.colorSpace = THREE.SRGBColorSpace;
    spriteMat.colorNode = tex.bilinear(remappedUV);
    spriteMat.needsUpdate = true;
  }).catch(() => {});

  const spriteGeo = new PlaneGeometry(planeW, planeH);
  spriteMesh = new Mesh(spriteGeo, spriteMat);
  spriteMesh.position.set(0, 0, -0.05);
  spriteMesh.renderOrder = 1;
  group.add(spriteMesh);

  // ---- Backdrop gradient panel (so no flat void behind title) ----
  const backdropW = 3.2;
  const backdropH = 1.2;
  const backdropMat = new MeshBasicNodeMaterial({ transparent: true, depthWrite: false });
  backdropMat.colorNode = Fn(() => {
    const t = uv().y;
    const top = vec3(0.043, 0.043, 0.063); // surface-ish
    const mid = vec3(0.086, 0.086, 0.114); // ink-ish
    const bot = vec3(0.030, 0.030, 0.045);
    const g1 = mix(bot, mid, smoothstep(0.0, 0.5, t));
    const g2 = mix(g1, top, smoothstep(0.5, 1.0, t));
    return g2;
  })();
  const backdrop = new Mesh(new PlaneGeometry(backdropW, backdropH), backdropMat);
  backdrop.position.set(0, 0, -0.15);
  backdrop.renderOrder = 0;
  group.add(backdrop);

  // ---- Grain overlay (subtle) ----
  const grainMat = new MeshBasicNodeMaterial({ transparent: true, depthWrite: false, opacity: 0.08 });
  grainMat.colorNode = Fn(() => {
    const n = uv().x.add(uv().y).add(time.mul(0.3)).fract().mul(0.06);
    return vec3(n);
  })();
  const grain = new Mesh(new PlaneGeometry(planeW, planeH), grainMat);
  grain.position.set(0, 0, 0.01);
  grain.renderOrder = 2;
  group.add(grain);

  // ---- Headline text "Journal" via font atlas ----
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const textMeshes = [];
  for (const item of items) {
    if (item.role === 'headline' || item.text === 'Journal') {
      const tx = ctx.fontAtlas.createText(item.text || '', {
        fontSize: 96,
        color: paper,
        align: 'center',
      });
      // scale pixel-space text into scene units (headline 0.34 em)
      const s = 0.0042;
      tx.scale.set(s, s, s);
      tx.position.set(0, 0, 0.02);
      tx.renderOrder = 3;
      group.add(tx);
      textMeshes.push(tx);
    }
  }

  // ---- Entrance motion (rise-in + weighted-settle) ----
  const tl = gsap.timeline();
  group.position.y += 0.4;
  group.position.z = group.position.z; // adapter handles final, but motion offset local
  tl.to(group.position, { y: group.position.y - 0.4, duration: 0.7, ease: 'power3.out' });
  tl.from(group.scale, { x: 1.04, y: 1.04, z: 1.04, duration: 0.9, ease: 'power4.out' }, '<');
  tl.from(backdrop.material, { opacity: 0, duration: 0.6, ease: 'power2.out' }, 0);
  tl.from(spriteMat, { opacity: 0, duration: 0.6, ease: 'power2.out' }, 0.1);

  // ---- UserData ----
  group.userData.handlers = {};
  group.userData.cleanup = () => {
    tl.kill();
    texLayer && undefined;
    spriteGeo.dispose();
    spriteMat.dispose();
    backdrop.geometry.dispose();
    backdrop.material.dispose();
    grain.geometry.dispose();
    grain.material.dispose();
    atlasTexture && atlasTexture.dispose && atlasTexture.dispose();
    textMeshes.forEach((m) => {
      if (m.geometry) m.geometry.dispose && m.geometry.dispose();
      if (m.material) m.material.dispose && m.material.dispose();
    });
  };

  return group;
}
